def calc(acq=4000000,wm=1,permit=4,opening=8,rate=.045,occ=.95,om=1,cap=.055,ramp=.9):
 cost=acq*(1+p['Acquisition_Duty'])+p['Legal_Diligence']+p['Working_Capital']+p['Works_Base']*wm*(1+p['Professional_Fee'])*(1+p['Contingency'])*(1+p['Works_VAT'])+p['Rooms']*p['Furniture_Per_Room'];debt=cost*p['Debt_Ratio'];payment=debt*(rate/4)/(1-(1+rate/4)**(-p['Debt_Term']*4)) if rate else debt/(p['Debt_Term']*4);balance=0;qs=[]
 for q in range(81):
  spend=(acq*(1+p['Acquisition_Duty'])+p['Legal_Diligence']+p['Working_Capital']) if q==0 else 0
  if 0<q<=permit:spend+=p['Works_Base']*wm*p['Professional_Fee']*(1+p['Contingency'])*(1+p['Works_VAT'])/permit
  if permit<q<=opening:spend+=p['Works_Base']*wm*(1+p['Contingency'])*(1+p['Works_VAT'])/(opening-permit)
  if q==opening:spend+=p['Rooms']*p['Furniture_Per_Room']
  draw=spend*p['Debt_Ratio'];interest=(balance+draw/2)*rate/4 if q else 0;principal=min(balance,max(0,payment-interest)) if q>opening else 0;balance+=draw-principal;qs.append([spend,draw,interest+principal,balance,debt*p['Debt_Fee'] if q==0 else 0])
 cf=[];eq=[];nois=[];devs=[];terminal=0
 for y in range(21):
  quarters=[qs[0]] if y==0 else qs[1+(y-1)*4:1+y*4];dev=sum(q[0] for q in quarters);ds=sum(q[2]+q[4] for q in quarters);draw=sum(q[1] for q in quarters);fraction=min(1,max(0,(y*4-opening)/4));st=ramp if y==math.floor(opening/4)+1 else 1
  receipts=p['Rooms']*(p['Base_Rent']+p['Charges'])*p['Letting_Months']*occ*(1-p['Arrears_Rate'])*fraction*st*(1+p['Rent_Growth'])**(y-1) if y else 0
  opex=(p['Fixed_Opex']+p['Rooms']*p['Variable_Opex'])*om*fraction*(1+p['Expense_Growth'])**(y-1) if y else 0;noi=receipts*(1-p['Management_Fee'])-opex;replacement=p['Rooms']*p['Replacement_Per_Room']*fraction*(1+p['Expense_Growth'])**(y-1) if y else 0
  if y in [10,15]:replacement+=p['Rooms']*p['Refurb_Per_Room']*(1+p['Expense_Growth'])**(y-1)
  if y==20:terminal=(p['Rooms']*(p['Base_Rent']+p['Charges'])*p['Letting_Months']*occ*(1-p['Arrears_Rate'])*(1-p['Management_Fee'])*(1+p['Rent_Growth'])**20-(p['Fixed_Opex']+p['Rooms']*p['Variable_Opex'])*om*(1+p['Expense_Growth'])**20)/cap*(1-p['Selling_Fee'])
  c=noi-replacement-dev+(terminal+p['Working_Capital'] if y==20 else 0);cf.append(c);eq.append(c+draw-ds-(balance if y==20 else 0));nois.append(noi);devs.append(dev)
 return {'NPV':sum(v/(1+p['Project_Rate'])**t for t,v in enumerate(cf)),'equity_NPV':sum(v/(1+p['Equity_Rate'])**t for t,v in enumerate(eq)),'CF':cf,'equity_CF':eq,'NOI':nois,'capex':cost,'terminal':terminal,'debt_final':balance,'devs':devs,'quarters':qs}
base=calc();cases={'Downside':calc(acq=4400000,wm=1.2,permit=5,opening=12,rate=.06,occ=.85,om=1.15,cap=.065,ramp=.8),'Base':base,'Upside':calc(acq=3600000,wm=.9,permit=3,opening=6,rate=.035,occ=.98,om=.95,cap=.05,ramp=.95)}
